WITH valid_employees AS (SELECT * FROM employees WHERE MONTH(hire_date) IN (5, 8, 10) AND job_title NOT IN ('Analyst', 'Designer', 'Manager') AND full_name LIKE 'H%'), summary AS (SELECT is_remote, QUARTER(hire_date) AS hire_quarter, MAX(salary) AS max_salary, SUM(CASE WHEN level = 'L4' THEN 1 ELSE 0 END) AS l4_count FROM valid_employees GROUP BY is_remote, QUARTER(hire_date)) SELECT is_remote, hire_quarter, max_salary, l4_count FROM summary ORDER BY l4_count DESC, is_remote, hire_quarter LIMIT 3
